def solve(events):
    balances = {}
    seen = set()
    applied = {}
    cancelled = set()
    for e in events:
        t = e['type']
        if t == 'deposit' or t == 'withdraw':
            i = e['id']
            if i in seen:
                continue
            seen.add(i)
            k = e['account']
            if k not in balances:
                balances[k] = 0
            a = e['amount']
            if t == 'deposit':
                balances[k] += a
                applied[i] = (k, a)
            elif balances[k] >= a:
                balances[k] -= a
                applied[i] = (k, -a)
        elif t == 'cancel':
            i = e['target']
            if i in applied and i not in cancelled:
                k, delta = applied[i]
                balances[k] -= delta
                cancelled.add(i)
    return [[k, balances[k]] for k in sorted(balances)]

