def solve(events):
    balances = {}
    used = set()
    applied = {}
    cancelled = set()
    for e in events:
        if e['type'] == 'cancel':
            target = e['target']
            if target in applied and target not in cancelled:
                account, change = applied[target]
                balances[account] -= change
                cancelled.add(target)
        else:
            ident = e['id']
            if ident not in used:
                used.add(ident)
                account = e['account']
                if account not in balances:
                    balances[account] = 0
                amount = e['amount']
                if e['type'] == 'deposit':
                    balances[account] += amount
                    applied[ident] = (account, amount)
                elif e['type'] == 'withdraw' and balances[account] >= amount:
